            raise ValueError("Missing required keys: 'Country' or 'Population'")
        country = entry["Country"]
        population = entry["Population"]
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population cannot be negative")
        countries.append(country)
        populations.append(math.floor(population))

    df = pd.DataFrame({"Country": countries, "Population": populations})
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except Exception:
        raise IOError("Cannot write to the specified directory")
    return file_path, df

import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    for key in key_path:
        data = data[key]
    if not isinstance(data, list):
        data = [data]
    numeric_data = []
    for item in data:
        try:
            numeric_data.append(float(item))
        except:
            pass
    if not numeric_data:
        raise ValueError("No numeric data found")
    fig, ax = plt.subplots()
    sns.boxplot(data=numeric_data, ax=ax)
    return fig

import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    for key in key_path:
        if key not in data:
            raise KeyError(f"Key '{key}' not found")
        data = data[key]
    if not isinstance(data, list) or not data:
        raise ValueError("No numeric data found")
    numeric_data = []
    for item in data:
        try:
            numeric_data.append(float(item))
        except (TypeError, ValueError):
            raise ValueError("Data contains non‑numeric values")
    fig, ax = plt.subplots()
    sns.boxplot(data=numeric_data, ax=ax)
    ax.set_title('Boxplot of Extracted Data')
    return fig
